public sealed record SubmitExpenseReportCommand(
    Guid OrganizationId,
    Guid EmployeeId,
    List<CreateLineItemDto> LineItems
) : IRequest<Result<Guid>>;

public sealed record CreateLineItemDto(
    LineItemCategory Category,
    Money Amount,
    DateOnly Date,
    string? Description,
    Guid? ReceiptId
);

public sealed class SubmitExpenseReportHandler : IRequestHandler<SubmitExpenseReportCommand, Result<Guid>>
{
    private readonly IExpenseReportRepository _reports;
    private readonly IPolicyEngine _policy;
    private readonly IUnitOfWork _uow;
    private readonly ILogger<SubmitExpenseReportHandler> _log;

    public SubmitExpenseReportHandler(
        IExpenseReportRepository reports,
        IPolicyEngine policy,
        IUnitOfWork uow,
        ILogger<SubmitExpenseReportHandler> log)
    {
        _reports = reports;
        _policy = policy;
        _uow = uow;
        _log = log;
    }

    public async Task<Result<Guid>> Handle(SubmitExpenseReportCommand request, CancellationToken ct)
    {
        _log.LogInformation("Submitting expense report for employee {EmployeeId}", request.EmployeeId);

        var report = new ExpenseReport(request.EmployeeId, request.OrganizationId);
        foreach (var line in request.LineItems)
        {
            report.AddLineItem(line.ToDomain());
        }

        try
        {
            report.Submit(_policy);
        }
        catch (DomainException ex)
        {
            _log.LogWarning(ex, "Policy validation failed for report draft.");
            return Result<Guid>.Failure([ex.Message]);
        }

        await _reports.AddAsync(report, ct);
        await _uow.SaveChangesAsync(ct);

        return Result<Guid>.Success(report.Id);
    }
}

