import axios from 'axios';
import type { AxiosError } from 'axios';
import type { ExpenseReport, LineItem } from './types';

const api = axios.create({ baseURL: import.meta.env.VITE_API_URL });

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('auth_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

api.interceptors.response.use(
  (res) => res,
  (err: AxiosError<{ title: string; detail: string }>) => {
    const msg = err.response?.data?.detail ?? 'Something went wrong';
    return Promise.reject(new Error(msg));
  }
);

export const submitExpenseReport = async (
  orgId: string,
  items: Omit<LineItem, 'id'>[]
): Promise<ExpenseReport> => {
  const { data } = await api.post('/api/expense-reports', {
    organizationId: orgId,
    lineItems: items.map((i) => ({
      category: i.category,
      amount: { amount: i.amount.amount, currency: i.amount.currency },
      date: i.date,
      description: i.description,
    })),
  });
  return data;
};

// Infer response shape from backend
interface SubmitResponse {
  id: string;
  status: 'Draft' | 'Submitted' | 'Approved' | 'Rejected' | 'Paid';
  totalAmount: { amount: number; currency: string };
  submittedAt?: string;
}

// src/features/expense-reports/hooks.ts
export function useSubmitExpenseReport() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: submitExpenseReport,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['expense-reports'] });
    },
  });
}

// src/features/expense-reports/components/NewExpenseReportForm.tsx
'use client';
import { useState } from 'react';
import { useSubmitExpenseReport } from '../hooks';
import type { LineItemCategory } from '../types';

const CATEGORIES: LineItemCategory[] = [
  'Meals', 'Travel', 'Lodging', 'Transport', 'Software', 'Equipment', 'Other'
];

export function NewExpenseReportForm({ organizationId }: { organizationId: string }) {
  const [items, setItems] = useState<CreateLineItem>([emptyItem()]);
  const mutation = useSubmitExpenseReport();
  const [error, setError] = useState<string | null>(null);

  const addItem = () => setItems((prev) => [...prev, emptyItem()]);
  const removeItem = (index: number) =>
    setItems((prev) => prev.filter((_, i) => i !== index));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await mutation.mutateAsync({ organizationId, lineItems: items });
      alert('Report submitted successfully!');
      setItems([emptyItem()]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Submission failed');
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <h2 className="text-xl font-semibold">New Expense Report</h2>
      {items.map((item, idx) => (
        <div key={idx} className="grid grid-cols-1 sm:grid-cols-5 gap-2">
          <select
            value={item.category}
            onChange={(e) => updateItem(idx, 'category', e.target.value as LineItemCategory)}
          >
            {CATEGORIES.map((c) => (
              <option key={c} value={c}>{c}</option>
            ))}
          </select>
          <input
            type="number"
            step="0.01"
            value={item.amount}
            onChange={(e) => updateItem(idx, 'amount', parseFloat(e.target.value))}
            placeholder="Amount"
          />
          <input
            type="date"
            value={item.date}
            onChange={(e) => updateItem(idx, 'date', e.target.value)}
          />
          <input
            value={item.description ?? ''}
            onChange={(e) => updateItem(idx, 'description', e.target.value)}
            placeholder="Description"
          />
          <button type="button" onClick={() => removeItem(idx)} className="btn btn-danger">
            Remove
          </button>
        </div>
      ))}
      <button type="button" onClick={addItem} className="btn btn-secondary">
        Add Line Item
      </button>
      {error && <p className="text-red-500">{error}</p>}
      <button type="submit" disabled={mutation.isPending} className="btn btn-primary">
        {mutation.isPending ? 'Submitting...' : 'Submit Report'}
      </button>
    </form>
  );
}

function emptyItem(): CreateLineItem {
  return {
    category: 'Other',
    amount: 0,
    date: new Date().toISOString().slice(0, 10),
    description: '',
  };
}

function updateItem(idx: number, field: keyof CreateLineItem, value: string | number) {
  setItems((prev) => {
    const next = [...prev];
    next[idx] = { ...next[idx], [field]: value };
    return next;
  });
}
